// Package docs holds the checked-in OpenAPI spec (swagger.json, generated by
// `task docs`) served at /openapi.json and rendered by the Scalar UI at
// /docs. No Swagger UI runtime dependency: the spec is embedded as JSON.
package docs

import _ "embed"

// Spec is the raw OpenAPI (Swagger 2.0) document. The host/scheme fields are
// rewritten per request by internal/web before serving.
//
//go:embed swagger.json
var Spec []byte
